/** Documentary contract, not an implemented execution API or database migration. */
export type OrderCopy = readonly [string, string, string];
export type OrderField = { path: string; type: string; when: 'create' | 'authorize' | 'submit' | 'event' | 'settle' | 'conditional'; copy: OrderCopy };
const f = (path: string, type: string, when: OrderField['when'], pt: string, en: string, es: string): OrderField => ({ path, type, when, copy: [pt, en, es] });
export const orderCopy = {
  title: ['Estrutura padronizada da ordem', 'Standardized order structure', 'Estructura estandarizada de la orden'],
  lead: ['Uma ordem é o registro estruturado de uma operação proposta pela BETTEX. Ela reúne a instrução versionada e os vínculos com análise, autorização, reserva, execução e resultado. Criar o registro não autoriza investir nem comprova execução.',
    'An order is the structured record of an operation proposed by BETTEX. It joins the versioned instruction with links to analysis, authorization, reservation, execution and results. Creating the record neither authorizes investment nor proves execution.',
    'Una orden es el registro estructurado de una operación propuesta por BETTEX. Reúne la instrucción versionada y los vínculos con análisis, autorización, reserva, ejecución y resultado. Crear el registro no autoriza invertir ni acredita ejecución.'],
  scope: ['Este é o padrão documental proposto para ordens de investimento, redução e encerramento de posições. Não descreve uma API já entregue: o demo permanece exclusivamente visual. Pagamentos de staking, vendas de tokens e transferências da tesouraria têm regras próprias e não se tornam ordens de investimento por usarem USDC.',
    'This is the proposed documentary standard for investment, position-reduction and position-closing orders. It does not describe an already-delivered API: the demo remains visual only. Staking payments, token sales and treasury transfers have their own rules; using USDC does not turn them into investment orders.',
    'Este es el estándar documental propuesto para órdenes de inversión, reducción y cierre de posiciones. No describe una API ya entregada: el demo sigue siendo exclusivamente visual. Los pagos de staking, las ventas de tokens y las transferencias de tesorería tienen reglas propias; usar USDC no las convierte en órdenes de inversión.'],
  distinctions: ['Proposta é a alternativa analisada; decisão é a escolha justificada da BETTEX; ordem é a instrução registrada. Uma ordem coordenada pode conter várias partes, cada uma com identificador e acompanhamento próprios. A ordem enviada à plataforma é uma representação dessa parte, não outro investimento a somar.',
    'A proposal is an analyzed alternative; a decision is BETTEX’s reasoned selection; an order is the recorded instruction. A coordinated order can contain several legs, each with its own identifier and tracking. The order sent to a platform represents that leg; it is not another investment to add.',
    'La propuesta es la alternativa analizada; la decisión es la elección justificada de BETTEX; la orden es la instrucción registrada. Una orden coordinada puede contener varias partes, cada una con identificador y seguimiento propios. La orden enviada a la plataforma representa esa parte; no es otra inversión que sumar.'],
  storage: ['A tesouraria conserva o vínculo contábil com a ordem, suas reservas, custos e movimentos. O registro lógico pode estar distribuído entre serviços, mas os identificadores permitem reconstruir a mesma operação. A instrução aprovada é imutável; confirmações e mudanças de estado são eventos acrescentados ao histórico, não alterações retroativas do conteúdo autorizado.',
    'The treasury retains the accounting link to the order, its reservations, costs and movements. The logical record may span services, but its identifiers reconstruct the same operation. The approved instruction is immutable; confirmations and state changes are appended events, not retroactive changes to authorized content.',
    'La tesorería conserva el vínculo contable con la orden, sus reservas, costos y movimientos. El registro lógico puede distribuirse entre servicios, pero los identificadores permiten reconstruir la misma operación. La instrucción aprobada es inmutable; las confirmaciones y los cambios de estado son eventos añadidos, no cambios retroactivos del contenido autorizado.'],
  detailTitle: ['Contrato técnico da ordem: campos, tipos e obrigatoriedade', 'Technical order contract: fields, types and requirements', 'Contrato técnico de la orden: campos, tipos y obligatoriedad'],
  detailLink: ['Consultar a tabela técnica completa da ordem', 'Read the complete technical order table', 'Consultar la tabla técnica completa de la orden'],
  selectionTitle: ['Critérios de seleção e evolução da decisão', 'Selection criteria and decision evolution', 'Criterios de selección y evolución de la decisión'],
  selectionInitial: ['Inicialmente, a seleção das oportunidades usa critérios determinísticos: os mesmos dados, a mesma estratégia e a mesma versão dos critérios devem produzir a mesma classificação e o mesmo desempate. Isso descreve o ponto de partida, não a inteligência probabilística que o projeto precisa desenvolver.',
    'Initially, opportunity selection uses deterministic criteria: the same data, strategy and criteria version must produce the same ranking and tie-break. This describes the starting point, not the probabilistic intelligence the project must develop.',
    'Inicialmente, la selección de oportunidades usa criterios deterministas: los mismos datos, estrategia y versión de criterios deben producir la misma clasificación y desempate. Esto describe el punto de partida, no la inteligencia probabilística que el proyecto debe desarrollar.'],
  selectionEligibility: ['Primeiro, verificar elegibilidade: mercado disponível e autorizado, estratégia dentro do mandato, dados e cotações válidos, liquidez executável, custos estimáveis e capital compatível com a parcela investível. Ausência de informação essencial, conector sem permissão ou restrição vigente impede avançar. Esta triagem não substitui a aprovação independente de risco.',
    'First, check eligibility: an available and authorized market, a strategy within its mandate, valid data and quotes, executable liquidity, estimable costs and capital compatible with the investable allocation. Missing essential information, an unpermitted connector or an active restriction prevents advancement. This screening does not replace independent risk approval.',
    'Primero, verificar elegibilidad: mercado disponible y autorizado, estrategia dentro del mandato, datos y cotizaciones válidos, liquidez ejecutable, costos estimables y capital compatible con la parte invertible. La falta de información esencial, un conector sin permiso o una restricción vigente impiden avanzar. Este filtro no sustituye la aprobación independiente de riesgo.'],
  selectionRanking: ['Entre candidatas elegíveis e comparáveis, a referência inicial é ordenar por maior retorno líquido projetado por USDC comprometido, no mesmo horizonte e em classe de risco comparável. Considerar principal e custos de entrada, saída, execução e conversão. Em empate, comparar, nesta sequência: menor perda no cenário adverso definido pela estratégia; menor prazo de imobilização; menor exposição correlacionada com a carteira; maior liquidez executável. Se o empate persistir, usar o identificador estável da proposta. A estratégia deve versionar os cálculos, as hipóteses, os cenários e os limites mínimos de aceitação; não há pesos ou percentuais universais implícitos.',
    'Among eligible, comparable candidates, the initial reference is to rank by higher projected net return per committed USDC, over the same horizon and within a comparable risk class. Include principal and entry, exit, execution and conversion costs. For ties, compare in this order: lower loss in the strategy-defined adverse scenario; shorter lock-up; lower correlation with portfolio exposure; greater executable liquidity. Break remaining ties using the stable proposal identifier. The strategy must version calculations, assumptions, scenarios and minimum acceptance thresholds; no universal weights or percentages are implied.',
    'Entre candidatas elegibles y comparables, la referencia inicial es ordenar por mayor rentabilidad neta proyectada por USDC comprometido, en el mismo horizonte y una clase de riesgo comparable. Considerar capital y costos de entrada, salida, ejecución y conversión. En empate, comparar en este orden: menor pérdida en el escenario adverso definido por la estrategia; menor plazo de inmovilización; menor exposición correlacionada con la cartera; mayor liquidez ejecutable. Si persiste, usar el identificador estable de la propuesta. La estrategia debe versionar cálculos, supuestos, escenarios y umbrales mínimos de aceptación; no hay pesos o porcentajes universales implícitos.'],
  selectionAbstain: ['Retorno projetado é uma estimativa, não lucro realizado nem promessa de ganho. Se os horizontes ou riscos não forem comparáveis, as premissas não tiverem suporte verificável ou nenhuma candidata atender aos critérios, BETTEX não força uma escolha: registra a abstenção e solicita nova análise. A candidata selecionada ainda passa pela validação independente de risco e pela reserva antes do envio.',
    'Projected return is an estimate, not realized profit or a promise of gains. If horizons or risks are incomparable, assumptions lack verifiable support or no candidate meets the criteria, BETTEX does not force a choice: it records abstention and requests new analysis. The selected candidate still undergoes independent risk validation and reservation before submission.',
    'La rentabilidad proyectada es una estimación, no ganancia realizada ni promesa de beneficios. Si horizontes o riesgos no son comparables, los supuestos carecen de respaldo verificable o ninguna candidata cumple los criterios, BETTEX no fuerza una elección: registra la abstención y solicita otro análisis. La candidata seleccionada aún pasa por validación independiente de riesgo y reserva antes del envío.'],
  selectionPhases: ['A decisão probabilística deve ser implementada na ALFA ou na BETA. Nessa evolução, o agente BETTEX incorpora inferências e avaliações de incerteza com apoio dos subagentes de risco e tesouraria, em vez de permanecer limitado à ordenação fixa. A fase exata de entrada e os modelos ainda precisam ser definidos e validados. Os controles de segurança, permissões, limites e aprovação independente continuam obrigatórios, mesmo quando a decisão passa a ser probabilística.',
    'Probabilistic decision-making must be implemented in ALFA or BETA. In that evolution, the BETTEX agent incorporates inference and uncertainty assessment with support from risk and treasury subagents, rather than remaining limited to fixed ranking. The exact introduction phase and models still require definition and validation. Safety controls, permissions, limits and independent approval remain mandatory even when decision-making becomes probabilistic.',
    'La decisión probabilística debe implementarse en ALFA o BETA. En esa evolución, el agente BETTEX incorpora inferencias y evaluación de incertidumbre con apoyo de los subagentes de riesgo y tesorería, en vez de limitarse a una clasificación fija. La fase exacta de incorporación y los modelos aún requieren definición y validación. Los controles de seguridad, permisos, límites y aprobación independiente siguen siendo obligatorios aunque la decisión pase a ser probabilística.'],
  selectionDemo: ['O demo exclusivamente visual ilustra esse percurso, mas não permite comprovar com garantia absoluta uma decisão probabilística real, sua confiabilidade ou sua validação operacional. Não apresentar uma classificação roteirizada como inferência real. Nem o demo nem os modelos futuros oferecem certeza absoluta sobre os mercados ou garantia de rentabilidade.',
    'The visual-only demo illustrates this journey but cannot establish with absolute assurance a real probabilistic decision, its reliability or its operational validation. Do not present scripted ranking as real inference. Neither the demo nor future models offer absolute market certainty or guaranteed returns.',
    'El demo exclusivamente visual ilustra este recorrido, pero no permite acreditar con garantía absoluta una decisión probabilística real, su fiabilidad o su validación operativa. No presentar una clasificación guionizada como inferencia real. Ni el demo ni los modelos futuros ofrecen certeza absoluta sobre mercados o garantía de rentabilidad.'],
  selectionTrace: ['Cada revisão da ordem registra o método de seleção, a versão dos critérios e a comparação que justifica a escolha. Quando houver decisão probabilística, preservar também a identificação e a versão do modelo, a referência da inferência, seus dados de entrada, parâmetros e saída observada. Esses campos não podem ser preenchidos com inferências inventadas no demo.',
    'Each order revision records the selection method, criteria version and comparison justifying the choice. For probabilistic decisions, also retain model identity and version, the inference reference, its inputs, parameters and observed output. These fields must not be populated with fabricated demo inferences.',
    'Cada revisión de la orden registra el método de selección, la versión de criterios y la comparación que justifica la elección. Para decisiones probabilísticas, conservar también identidad y versión del modelo, referencia de inferencia, datos de entrada, parámetros y salida observada. No completar estos campos con inferencias inventadas en el demo.'],
  tableIntro: ['Os caminhos abaixo definem um registro lógico completo. [] indica uma coleção. As coleções de histórico começam vazias e recebem registros apenas quando o fato ocorre. Os campos condicionais exigem condição comprovada; não usar zero para representar desconhecido. Referências apontam para registros imutáveis, versionados e recuperáveis, não para dados que possam mudar silenciosamente.',
    'The paths below define a complete logical record. [] denotes a collection. History collections start empty and receive entries only when the fact occurs. Conditional fields require a proven condition; zero must not represent unknown data. References point to immutable, versioned, retrievable records, not silently changeable data.',
    'Las rutas siguientes definen un registro lógico completo. [] indica una colección. Las colecciones históricas empiezan vacías y reciben registros solo cuando ocurre el hecho. Los campos condicionales exigen una condición comprobada; cero no representa un dato desconocido. Las referencias apuntan a registros inmutables, versionados y recuperables, no a datos que puedan cambiar silenciosamente.'],
  primitivesTitle: ['Tipos comuns e representação dos valores', 'Common types and value representation', 'Tipos comunes y representación de valores'],
  lifecycleTitle: ['Estados da ordem e fatos que permitem avançar', 'Order states and evidence required to advance', 'Estados de la orden y hechos necesarios para avanzar'],
  returnTitle: ['Como o registro permite apurar o retorno', 'How the record supports return calculation', 'Cómo el registro permite calcular el retorno'],
  returnText: ['Uma compra executada pode abrir uma posição sem realizar lucro. Ordens de redução ou encerramento referenciam os mesmos lotes; recebimentos, custos e ajustes são associados às quantidades efetivamente encerradas. O cálculo reúne entrada e saída pelos identificadores de posição, nunca só pelo saldo da carteira ou pelo estado “executada” de uma ordem.',
    'An executed purchase can open a position without realizing profit. Reduction or closing orders reference the same lots; receipts, costs and adjustments are allocated to quantities actually closed. Calculation joins entry and exit through position identifiers, never just wallet balance or an order’s “filled” state.',
    'Una compra ejecutada puede abrir una posición sin realizar ganancias. Las órdenes de reducción o cierre referencian los mismos lotes; cobros, costos y ajustes se asignan a las cantidades efectivamente cerradas. El cálculo reúne entrada y salida por identificadores de posición, nunca solo por el saldo de la billetera o el estado «ejecutada» de una orden.'],
  formula: ['Resultado realizado líquido = recebimentos comprovados das parcelas encerradas − principal atribuído a essas parcelas − custos efetivos atribuídos, sem duplicar taxas já descontadas dos recebimentos. Retorno percentual = resultado líquido ÷ capital efetivamente aplicado, incluindo custos de entrada, × 100. Denominador zero não produz percentual.',
    'Realized net result = verified proceeds from closed portions − principal allocated to those portions − allocated actual costs, without counting fees already deducted from proceeds twice. Percentage return = net result ÷ capital actually deployed, including entry costs, × 100. A zero denominator produces no percentage.',
    'Resultado realizado neto = cobros comprobados de las partes cerradas − capital asignado a esas partes − costos efectivos asignados, sin duplicar comisiones ya descontadas de los cobros. Rentabilidad porcentual = resultado neto ÷ capital efectivamente aplicado, incluidos costos de entrada, × 100. Un denominador cero no produce porcentaje.'],
  example: ['Exemplo apenas aritmético: entrada de 100 USDC com custo de 0,20; saída bruta de 110 com custo de 0,20. Resultado líquido: 9,60 USDC; capital aplicado: 100,20; retorno: aproximadamente 9,58%. Principal recuperado não é lucro. Valores esperados e valorização de posições abertas permanecem separados do realizado.',
    'Arithmetic example only: entry of 100 USDC with a 0.20 cost; gross exit of 110 with a 0.20 cost. Net result: 9.60 USDC; deployed capital: 100.20; return: approximately 9.58%. Recovered principal is not profit. Expected values and open-position appreciation remain separate from realized results.',
    'Ejemplo solo aritmético: entrada de 100 USDC con costo de 0,20; salida bruta de 110 con costo de 0,20. Resultado neto: 9,60 USDC; capital aplicado: 100,20; rentabilidad: aproximadamente 9,58%. El capital recuperado no es ganancia. Los valores esperados y la valorización de posiciones abiertas se mantienen separados del resultado realizado.'],
  settlement: ['O resultado usa o dia UTC da realização comprovada; o horário de chegada da confirmação não o redefine. Conciliação, disponibilidade de USDC, posições abertas e reservas ainda precisam ser verificadas antes de considerar lucro distribuível. Este contrato não muda o split, os limites nem as regras de pagamento já descritas.',
    'Results use the UTC day of proven realization; confirmation arrival time does not redefine it. Reconciliation, USDC availability, open positions and reservations still require checking before profit can be distributable. This contract changes neither the split, limits nor payment rules already described.',
    'El resultado usa el día UTC de la realización comprobada; la llegada de la confirmación no lo redefine. La conciliación, disponibilidad de USDC, posiciones abiertas y reservas aún deben verificarse antes de considerar una ganancia distribuible. Este contrato no cambia el reparto, los límites ni las reglas de pago ya descritas.'],
  invariantsTitle: ['Validação, persistência e proteção do registro', 'Validation, persistence and record protection', 'Validación, persistencia y protección del registro'],
  integrity: ['A autorização sela order_id + revision + content_hash, incluindo todas as partes, valores, custos, destinos e condições da instrução. A versão do schema, a revisão da ordem e a versão das regras são independentes. Uma alteração legítima cria nova revisão e nova validação de risco; não sobrescreve a anterior nem libera partes enviadas ou incertas.',
    'Authorization seals order_id + revision + content_hash, including every leg, amount, cost, destination and instruction condition. Schema version, order revision and policy version are independent. A legitimate change creates a new revision and risk validation; it neither overwrites the previous one nor releases sent or uncertain legs.',
    'La autorización sella order_id + revision + content_hash, incluidas todas las partes, importes, costos, destinos y condiciones de la instrucción. La versión del schema, la revisión de la orden y la versión de las reglas son independientes. Un cambio legítimo crea otra revisión y validación de riesgo; no sobrescribe la anterior ni libera partes enviadas o inciertas.'],
  atomicity: ['A transição que autoriza e reserva é indivisível e anterior ao envio. Um único executor reivindica cada parte de forma durável. Chaves de idempotência se vinculam ao conteúdo, não autorizam conteúdo diferente e não garantem, sozinhas, execução única na plataforma. Estado desconhecido exige consulta e conciliação antes de decidir qualquer novo envio.',
    'Authorization and reservation form an indivisible transition before submission. A single executor durably claims each leg. Idempotency keys bind to content, do not authorize different content and alone do not guarantee single execution at the platform. An unknown state requires querying and reconciliation before deciding on any new submission.',
    'La autorización y la reserva forman una transición indivisible anterior al envío. Un único ejecutor reclama cada parte de forma duradera. Las claves de idempotencia se vinculan al contenido, no autorizan contenido diferente y por sí solas no garantizan ejecución única en la plataforma. Un estado desconocido exige consulta y conciliación antes de decidir otro envío.'],
  audit: ['IDs externos são únicos dentro de plataforma, conta e tipo de evento; sua repetição não cria outra execução ou lançamento. A projeção de estado usa sequência e controle de concorrência. Correções acrescentam eventos vinculados ao original. Só evidências reconciliadas geram efeitos contábeis; o histórico bruto recebido não é prova automática de liquidação.',
    'External IDs are unique within platform, account and event type; repetition creates no extra fill or ledger entry. State projections use sequence and concurrency control. Corrections append events linked to the original. Only reconciled evidence generates accounting effects; raw received history does not automatically prove settlement.',
    'Los IDs externos son únicos por plataforma, cuenta y tipo de evento; repetirlos no crea otra ejecución o asiento. La proyección de estado usa secuencia y control de concurrencia. Las correcciones añaden eventos vinculados al original. Solo las evidencias conciliadas generan efectos contables; el historial bruto recibido no acredita automáticamente liquidación.'],
  privacy: ['A trilha pública expõe fatos financeiros verificáveis e referências sanitizadas. Chaves privadas, credenciais, tokens de API, dados pessoais e material de assinatura ficam fora do registro público e do conteúdo da ordem. Referências internas de conta não são credenciais. Evidências restritas mantêm controle de acesso; publicar um hash não torna seu conteúdo público.',
    'The public trail exposes verifiable financial facts and sanitized references. Private keys, credentials, API tokens, personal data and signing material stay outside the public record and order content. Internal account references are not credentials. Restricted evidence retains access control; publishing a hash does not publish its contents.',
    'La trazabilidad pública expone hechos financieros verificables y referencias saneadas. Las claves privadas, credenciales, tokens de API, datos personales y material de firma quedan fuera del registro público y del contenido de la orden. Las referencias internas de cuenta no son credenciales. Las evidencias restringidas conservan control de acceso; publicar un hash no publica su contenido.'],
  compatibility: ['Cada conector deve validar o mesmo núcleo e seu perfil de mercado antes de operar. Campos obrigatórios ausentes, valores fora da precisão, versões desconhecidas ou termos não suportados bloqueiam o envio. Um mercado futuro não ganha disponibilidade por aparecer no schema. Não há alavancagem nem capital em BETTEX para estas ordens.',
    'Each connector must validate the same core and its market profile before operating. Missing required fields, invalid precision, unknown versions or unsupported terms block submission. A future market gains no availability by appearing in the schema. These orders have no leverage and use no BETTEX as investment capital.',
    'Cada conector debe validar el mismo núcleo y su perfil de mercado antes de operar. Los campos obligatorios ausentes, precisión inválida, versiones desconocidas o términos no compatibles bloquean el envío. Un mercado futuro no queda disponible por aparecer en el schema. Estas órdenes no tienen apalancamiento ni capital de inversión en BETTEX.'],
  field: ['Campo técnico', 'Technical field', 'Campo técnico'],
  type: ['Tipo do dado', 'Data type', 'Tipo de dato'],
  requirement: ['Exigência e significado', 'Requirement and meaning', 'Exigencia y significado'],
} satisfies Record<string, OrderCopy>;

